        if not nFrame.Parent then return end
        local t = TweenService:Create(nFrame, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.In),
            { Size = UDim2.new(0, 0, 0, 55) })
        t:Play()
        t.Completed:Wait()
        nFrame:Destroy()
    end)
end

